    const mine = prep.side === 'h' ? r.hg : r.ag, th = prep.side === 'h' ? r.ag : r.hg;
    p.moral = clamp(p.moral + (mine > th ? 3 : mine < th ? -2 : 0) + (pst.rt >= 8 ? 3 : pst.rt < 5.5 ? -3 : 0), 0, 100);
