    const off = absDay() - T.start;
    if (off === TOUR_OFF.gEnd) jobs.push({ k: 'tourStage', ti, stage: 'groups' });
    for (const n of [16, 8, 4, 2]) if (TOUR_OFF[n] === off) jobs.push({ k: 'tourStage', ti, stage: n });
