  const P = inPhotos(); if (!P || IN_PH.wait || typeof Image === 'undefined') return IN_PH.wait;
  const q = typeof MEDIA_H !== 'undefined' && MEDIA_H.intro ? '?h=' + MEDIA_H.intro : '';
