    if (M.shoot) return `<div class="moment"><div class="lbl acc">Tirs au but</div><p class="q">${esc(M.shoot.q)}</p><div class="opts">${M.shoot.o.map((o, i) => `<button class="opt" data-a="lShoot" data-v="${i}"><b>${esc(o.t)}</b></button>`).join('')}</div></div>`;
