    const body = tab === 'rt' ? vRatings(M) : tab === 'sh' ? vShotMap(M) : tab === 'hm' ? vHeat(M) : tab === 'st' ? vLiveStats(M) : tab === 'fd' ? `<div class="lfeed" id="lFeed">${vFeed(M, 40)}</div>` : vLivePanel(M, P);
