  const fh = vFeed(M); if (fd && fd._h !== fh) { fd.innerHTML = fh; fd._h = fh; }
  const lc = $('#lCom'); if (lc) { const ch = vCom(M); if (lc._h !== ch) { lc.innerHTML = ch; lc._h = ch; } }
